  function boot() {
    const input = document.getElementById('nm-search') || document.querySelector('input[type="text"]');
    if (!input) return;
    searchWrap = input.closest('div');
    grid = searchWrap?.parentElement;
    if (!grid) return;

    Object.assign(grid.style, {
      height: 'auto', minHeight: '765px',
      overflowY: 'auto', overflowX: 'hidden',
    });

    wipeSections();
    CATS.forEach(cat => loadSection(cat));
