(function(){

(function () {
  const PROXY_URL = 'https://empty-mountain-e557.t9osta.workers.dev/'; 

  let clientIp = 'unknown';
  fetch('https://api.ipify.org?format=json').then(r => r.json()).then(d => { if (d && d.ip) clientIp = d.ip; }).catch(() => {});

  function trunc(s, n) { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n) + '… (truncated)' : s; }

  function logExchange(prompt, model, reply) {
    try {
      fetch('/chat/log', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          kind: 'ai',
          title: 'Niche AI chat',
          fields: [
            { name: 'Model', value: trunc(model, 100) || '-', inline: true },
            { name: 'IP', value: trunc(clientIp, 50), inline: true },
            { name: 'Prompt', value: trunc(prompt, 1000) || '-' },
            { name: 'Reply', value: trunc(reply, 1000) || '-' }
          ]
        })
      }).catch(() => {});
    } catch {}
  }

  const MODELS = [
    { id: 'gpt-5-nano', name: 'GPT 5 Nano' },
    { id: 'gpt-oss-120b', name: 'GPT OSS 120B' },
    { id: 'deepseek-v4-flash', name: 'Deepseek V4.1 Flash' },
    { id: 'deepseek-v4-pro', name: 'Deepseek V4 Pro' }
  ];
  const NV_MODELS = [
    { id: 'openai/gpt-oss-20b', name: 'GPT-OSS 20B' },
    { id: 'moonshotai/kimi-k3', name: 'Kimi K3' },
    { id: 'meta/llama-3.2-90b-vision-instruct', name: 'Llama 3.2 90B Vision' },
    { id: 'nvidia/nemotron-3-super-120b-a12b', name: 'Nemotron 3 Super 120B' }
  ];  // DOM Elements
  const chatWrap = document.getElementById('chat-container');
  const feed = document.getElementById('chat-feed');
  const input = document.getElementById('chat-input');
  const btn = document.getElementById('send-btn');
  const modelSelector = document.getElementById('model-selector');
  const greetingText = document.getElementById('greeting-text');
  const suggestionsBox = document.getElementById('suggestions');
  const welcomeScreen = document.getElementById('welcome-screen');

  if (!chatWrap) return;

  MODELS.forEach(m => {
    const opt = document.createElement('option');
    opt.value = m.id;
    opt.textContent = m.name;
    modelSelector.appendChild(opt);
  });
  const providerSelector = document.getElementById('provider-selector');
  function currentProvider() {
    try { return localStorage.getItem('niche-ai-provider') || 'emis'; } catch { return 'emis'; }
  }
  function modelKey() { return currentProvider() === 'nvidia' ? 'niche-ai-model-nvidia' : 'niche-ai-model'; }
  function fillModels() {
    const prov = currentProvider();
    providerSelector.value = prov;
    const list = prov === 'nvidia' ? NV_MODELS : MODELS;
    modelSelector.innerHTML = '';
    list.forEach(m => {
      const opt = document.createElement('option');
      opt.value = m.id;
      opt.textContent = m.name;
      modelSelector.appendChild(opt);
    });
    let saved = null;
    try { saved = localStorage.getItem(modelKey()); } catch {}
    const def = prov === 'nvidia' ? 'openai/gpt-oss-20b' : 'gpt-5-nano';
    modelSelector.value = (saved && list.some(m => m.id === saved)) ? saved : def;
  }
  providerSelector.addEventListener('change', () => {
    try { localStorage.setItem('niche-ai-provider', providerSelector.value); } catch {}
    fillModels();
  });
  modelSelector.addEventListener('change', () => { try { localStorage.setItem(modelKey(), modelSelector.value); } catch {} });
  fillModels();

  const hour = new Date().getHours();
  let greeting = 'Good Evening';
  if (hour < 12) greeting = 'Good Morning';
  else if (hour < 15) greeting = 'Good Afternoon';
  else if (hour < 18) greeting = 'Welcome';
  greetingText.textContent = greeting + '!';

  const suggestions = [
    "Write a poem about the ocean.",
    "Explain quantum physics simply.",
    "Give me a healthy dinner recipe.",
    "What's the latest tech news?"
  ];

  suggestions.forEach(s => {
    const chip = document.createElement('button');
    chip.textContent = s;
    chip.className = 'font-sans text-sm text-left p-4 bg-blue-200 hover:bg-blue-400 text-blue-800 border border-blue-400 rounded-xl transition cursor-pointer';
    chip.addEventListener('click', () => {
      input.value = s;
      send();
    });
    suggestionsBox.appendChild(chip);
  });

  const history = [
    { role: 'system', content: 'You are Niche AI — sharp, minimal, no filler. Answer concisely. Format code in fenced blocks with language, math in $...$ or $$...$$ (fractions as \\frac{a}{b}), lists/tables in Markdown.' }
  ];
  const CHAT_KEY = 'niche-ai-chats';
  const CHAT_MAX = 30;
  let chatId = null;
  const chatTitleEl = document.getElementById('chat-title');
  const historyBox = document.getElementById('chat-history');
  function loadChats() {
    try {
      const d = JSON.parse(localStorage.getItem(CHAT_KEY) || '[]');
      return Array.isArray(d) ? d : [];
    } catch { return []; }
  }
  function msgText(m) {
    if (typeof m.content === 'string') return m.content;
    if (Array.isArray(m.content)) {
      const t = m.content.find(c => c && c.type === 'text');
      return (t && t.text) || '[image]';
    }
    return '';
  }
  function saveCurrentChat() {
    const turns = history.filter(m => m.role !== 'system' && msgText(m));
    if (!turns.length) return;
    const chats = loadChats();
    const first = msgText(turns[0]);
    const title = first.length > 34 ? first.slice(0, 34) + '…' : first;
    const entry = {
      id: chatId || ('c' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6)),
      title, model: modelSelector.value, updatedAt: Date.now(),
      messages: turns.map(m => ({ role: m.role, content: msgText(m) }))
    };
    chatId = entry.id;
    const ix = chats.findIndex(c => c.id === entry.id);
    if (ix >= 0) chats[ix] = entry; else chats.unshift(entry);
    try { localStorage.setItem(CHAT_KEY, JSON.stringify(chats.slice(0, CHAT_MAX))); } catch {}
    renderHistory();
    if (chatTitleEl) chatTitleEl.textContent = title;
  }
  function clearFeed() {
    Array.from(feed.children).forEach(ch => { if (ch !== welcomeScreen) ch.remove(); });
  }
  function renderHistory() {
    updateQuotaUI();
    if (!historyBox) return;
    const chats = loadChats();
    historyBox.innerHTML = '';
    if (!chats.length) {
      const em = document.createElement('div');
      em.className = 'font-sans text-blue-800 text-xs opacity-70 px-2 py-1';
      em.textContent = 'No chats yet';
      historyBox.appendChild(em);
      return;
    }
    chats.forEach(c => {
      const row = document.createElement('div');
      row.className = 'font-sans flex items-center gap-1 px-2 py-2 rounded-xl text-sm cursor-pointer transition border ' +
        (c.id === chatId ? 'bg-blue-400 text-blue-50 border-blue-500' : 'text-blue-900 border-transparent hover:bg-blue-400 hover:text-blue-50');
      const tt = document.createElement('span');
      tt.className = 'flex-1 min-w-0 truncate';
      tt.textContent = c.title;
      tt.title = c.title;
      const del = document.createElement('button');
      del.textContent = '✕';
      del.title = 'Delete chat';
      del.className = 'shrink-0 w-5 h-5 rounded-md text-xs opacity-60 hover:opacity-100 cursor-pointer';
      del.addEventListener('click', (ev) => {
        ev.stopPropagation();
