  function texToMixed(s) {
    // AI writes mixed numbers as 7\tfrac{2}{7} (not real KaTeX) -> 7 + thin space + fraction
    return String(s)
      .replace(/(\d)\\tfrac\{([^{}]*)\}\{([^{}]*)\}/g, '$1\\,\\frac{$2}{$3}')
