  function extractMath(text) {
    var segs = [];
    function rep2(display, body) { segs.push({ display: display, body: body }); return '@@MATH' + (segs.length - 1) + '@@'; }
    var out = String(text);
    out = out.replace(/\\\[([\s\S]*?)\\\]/g, function (m, b) { return rep2(true, b); });
    out = out.replace(/\$\$([\s\S]*?)\$\$/g, function (m, b) { return rep2(true, b); });
    out = out.replace(/\\\(([\s\S]*?)\\\)/g, function (m, b) { return rep2(false, b); });
    out = out.replace(/\$([^$\n]+?)\$/g, function (m, b) { return rep2(false, b); });
