  const QUOTA_MAX = 30, QUOTA_WINDOW = 3 * 3600 * 1000, TOKENS_PER_MSG = 4096, TOKEN_MAX = QUOTA_MAX * TOKENS_PER_MSG;
  const USAGE_KEY = 'niche-ai-usage';
  function usageRead() {
    let arr = [];
    try { arr = JSON.parse(localStorage.getItem(USAGE_KEY) || '[]'); } catch {}
    if (!Array.isArray(arr)) arr = [];
    const now = Date.now();
    return arr
      .filter(x => x && typeof x.t === 'number' && now - x.t < QUOTA_WINDOW)
