  function updateUsageUI() {
    const ru = requestsUsed(), tu = tokensUsed(), pct = usagePct();
    const setBar = (id, p) => { const b = document.getElementById(id); if (b) b.style.width = Math.min(100, Math.round(p)) + '%'; };
    const setTxt = (id, t) => { const e = document.getElementById(id); if (e) e.textContent = t; };
    if (unlimitedOk) {
      setTxt('usage-req-text', '∞'); setTxt('usage-tok-text', '∞'); setTxt('usage-total-text', 'unlimited');
      setBar('usage-req-bar', 0); setBar('usage-tok-bar', 0); setBar('usage-total-bar', 0);
    } else {
