      setTxt('usage-tok-text', fmtTokens(tu) + ' / ' + fmtTokens(TOKEN_MAX));
      setTxt('usage-total-text', Math.round(pct) + '%');
      setBar('usage-req-bar', (ru / QUOTA_MAX) * 100);
      setBar('usage-tok-bar', (tu / TOKEN_MAX) * 100);
