        return;
      }
      ss.cancel();
      const u = new SpeechSynthesisUtterance(String(text || '').slice(0, 2000));
      u.onend = function () { if (speakCur && speakCur.btn === btn) { speakCur = null; btn.innerHTML = SVG_VOL; } };
      u.onerror = function () { if (speakCur && speakCur.btn === btn) { speakCur = null; btn.innerHTML = SVG_VOL; } };
