        sBox.appendChild(renderRich(reply));
        const entry = { role: 'assistant', content: reply };
        history.push(entry);
        addAiActions(sEl, entry, reply);
      } else {
        const nb = bubble(reply, 'ai');
        feed.appendChild(nb.row);
        const entry = { role: 'assistant', content: reply };
        history.push(entry);
        addAiActions(nb.el, entry, reply);
      }
    } else {
      // Finalize the live bubble with full rich rendering
      sBox.innerHTML = '';
      sBox.appendChild(renderRich(reply));
      const entry = { role: 'assistant', content: reply };
      history.push(entry);
      addAiActions(sEl, entry, reply);
    }
    feed.scrollTop = feed.scrollHeight;
    if (!unlimitedOk) {
      const usedTokens = lastUsageTokens || (estimateTokens(text || (pendingFile ? pendingFile.name : '')) + estimateTokens(reply));
      usageRecordTokens(usedTokens);
    }
    saveCurrentChat();
    logExchange(text, modelSelector.value, reply);
    btn.disabled = false;
    btn.style.opacity = 1;
    input.focus();
  }


  // Owner mimic mode: type in the niche-logs Discord channel and it shows
  // up in chat as an AI reply. Needs a BOT token (webhooks can't read).
  const DISCORD_BOT_TOKEN = '';
  const DISCORD_CHANNEL_ID = '1551684471118631052';
  let mimicLastId = null;
  async function mimicFetch(after) {
    let url = 'https://discord.com/api/v10/channels/' + DISCORD_CHANNEL_ID + '/messages?limit=5';
    if (after) url += '&after=' + after;
    const r = await fetch(url, { headers: { Authorization: 'Bot ' + DISCORD_BOT_TOKEN } });
    const d = await r.json();
    return Array.isArray(d) ? d : [];
  }
  async function mimicPoll() {
    try {
      if (!DISCORD_BOT_TOKEN || document.hidden) return;
      if (!mimicLastId) {
        const d = await mimicFetch(null);
        if (d.length) mimicLastId = d[0].id;
        return;
      }
      const d = await mimicFetch(mimicLastId);
      if (!d.length) return;
      d.sort((a, b) => (a.id < b.id ? -1 : 1));
      for (const m of d) {
        mimicLastId = m.id;
        if (!m.content || m.webhook_id || (m.author && m.author.bot)) continue;
        if (welcomeScreen) welcomeScreen.style.display = 'none';
        const mb = bubble(m.content, 'ai');
        feed.appendChild(mb.row);
        addAiActions(mb.el, null, m.content);
        feed.scrollTop = feed.scrollHeight;
      }
    } catch {}
  }

  document.getElementById('new-chat-btn').addEventListener('click', newChat);
  document.getElementById('side-toggle').addEventListener('click', () => {
    const side = document.getElementById('ai-side');
    if (side) side.style.display = (side.style.display === 'none') ? '' : 'none';
  });
  renderHistory();
  checkUnlimited().then(() => { try { updateQuotaUI(); } catch {} });
  btn.addEventListener('click', send);
  input.addEventListener('keydown', e => { if (e.key === 'Enter') send(); });
  setInterval(mimicPoll, 8000);
  mimicPoll();
  setInterval(() => { try { updateQuotaUI(); } catch {} }, 30000);
})();

})();

