  let activeUuid = null;
  let pingInterval = null;
  let queuePollTimer = null;
  let queueFails = 0;
  let abortCtrl = null;

  function apiKey() {
    let input = document.getElementById('apiKeyInput');
    let key = input ? input.value.trim() : "";

    if (!key) {
      key = prompt("Enter your Cloud Gaming API Key to launch:");
      if (input && key) {
        input.value = key; 
      }
    }
    return key;
  }

  function setupOverlay() {
    let overlay = document.getElementById('nicheOverlay');
    if (!overlay) {
      overlay = document.createElement('div');
      overlay.id = 'nicheOverlay';
