    if(txt) txt.textContent = main;
    if(subTxt) subTxt.textContent = sub;
  }

  function openOverlay(label) {
    setupOverlay();
    const overlay = document.getElementById('nicheOverlay');
    overlay.style.display = 'flex';
    document.getElementById('nicheLoading').style.display = 'flex';
    document.getElementById('nicheGameFrame').style.display = 'none';
    document.body.style.overflow = 'hidden';
    setStatus(`Loading ${label}…`);
  }

  function releaseWake() {
    try { if (window.nicheWake) { window.nicheWake.release().catch(() => {}); window.nicheWake = null; } } catch (e) {}
  }
  async function holdWake() {
    try {
      if (!('wakeLock' in navigator)) return;
      if (window.nicheWake) return;
      window.nicheWake = await navigator.wakeLock.request('screen');
