        window.nicheWake.addEventListener('release', () => { window.nicheWake = null; });
      } catch (e) {}
    } catch (e2) {}
  }
  function focusGame() {
    try {
      const frame = document.getElementById('nicheGameFrame');
      if (!frame || frame.style.display === 'none') return;
