    if (abortCtrl) { abortCtrl.abort(); abortCtrl = null; }
    activeUuid = null;
  }

  async function launch(game) {
    window.nicheLastWasSynapse = false;
    resetState();
    openOverlay(game.name);
    abortCtrl = new AbortController();
    launchLog('launch', game, 'key: ' + game.key);

    if (LOCAL_GAMES[game.key]) {
      setTimeout(() => {
        document.getElementById('nicheLoading').style.display = 'none';
        document.getElementById('nicheGameFrame').style.display = 'block';
        document.getElementById('nicheGameFrame').src = LOCAL_GAMES[game.key];
        launchLog('loaded', game, 'local: ' + LOCAL_GAMES[game.key]);
      }, 1200);
      return;
    }

    setStatus(`Launching ${game.name}…`);
    let res;
    try {
      res = await apiFetch(`/cloud/v1/createSession`, {
        method: "POST",
        headers: { "x-api-key": apiKey(), "Content-Type": "application/json" },
        body: JSON.stringify({ game_key: game.key }),
        signal: abortCtrl.signal,
      });
    } catch (e) {
      setStatus("Failed to reach API.", String(e));
      launchLog('error', game, 'createSession unreachable: ' + String(e && e.message || e));
      return;
    }

    if (!res.ok || !res.body) {
      const txt = await res.text().catch(() => "");
      setStatus("createSession failed.", txt || `HTTP ${res.status}`);
      launchLog('error', game, 'createSession failed: ' + (txt || ('HTTP ' + res.status)));
      return;
    }

    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let buf = "";
    let settled = false;

    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      buf += decoder.decode(value, { stream: true });
      let idx;
      while ((idx = buf.indexOf("\n")) >= 0) {
        const line = buf.slice(0, idx).trim();
        buf = buf.slice(idx + 1);
        if (!line) continue;
        let msg;
        try { msg = JSON.parse(line); } catch { continue; }
        await handleStreamMsg(msg, game);
        if (msg.status === "error" || msg.status === "finished_queue") { settled = true; return; }
      }
    }
    if (!settled) setStatus("Stream ended before slot ready.", "Tap the game again to retry.");
  }

  async function handleStreamMsg(msg, game) {
    switch (msg.status) {
      case "creating_account": setStatus("Creating account…", "Just a few seconds."); break;
      case "account_ready": setStatus("Account ready.", "Requesting game session…"); break;
      case "requesting_game": setStatus("Requesting game slot…"); break;
      case "queue":
        activeUuid = msg.uuid;
        setStatus(`In queue for ${game.name}`, `Position ${msg.queue_pos ?? "?"}`);
        pollQueue(game);
        break;
      case "finished_queue":
        activeUuid = msg.uuid || activeUuid;
        setStatus("Slot ready — starting game…");
        await startGame(game);
        break;
      case "error":
        setStatus("Error.", msg.error || "Unknown error.");
        launchLog('error', game, 'stream: ' + (msg.error || 'Unknown error.'));
        break;
    }
  }

  function queueDead(game, why) {    resetState();
    setStatus("Queue lost.", (why || "Session expired.") + " Tap the game again to retry.");
  }
  async function pollQueue(game) {
    if (!activeUuid) return;
