      if (!res.ok) throw new Error("HTTP " + res.status);
      const data = await res.json();
      queueFails = 0;
      if (data.status === "queue") {
        setStatus(`In queue for ${game.name}`, `Position ${data.queue_pos ?? "?"}`);
        queuePollTimer = setTimeout(() => pollQueue(game), (typeof data.queue_pos === "number" && data.queue_pos > 10) ? 20000 : 8000);
      } else if (data.status === "finished_queue") {
        setStatus("Slot ready — starting game…");
        await startGame(game);
      } else {
        queueDead(game, "Session is gone.");
      }
    } catch (e) {
      queueFails++;
      if (queueFails >= 8) { queueDead(game, "Could not reach queue."); return; }
